// Masks personal data before the alert is sent to the LLM (GDPR / KVKK).
// The number of masked values per type is also returned for auditing.
const patterns = [
  { name: 'EMAIL',          re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g },
  { name: 'IBAN',           re: /\bTR\d{2}\s?(?:\d{4}\s?){5}\d{2}\b/gi },
  { name: 'CARD',           re: /\b(?:\d[ -]?){13,19}\b/g },
  { name: 'PHONE',          re: /(?:\+90\s?|\b0)5\d{2}\s?\d{3}\s?\d{2}\s?\d{2}\b/g },
  { name: 'NATIONAL_ID',    re: /\b[1-9]\d{10}\b/g },
  { name: 'IP',             re: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g },
];

function mask(value, stats) {
  if (typeof value === 'string') {
    let s = value;
    for (const p of patterns) {
      s = s.replace(p.re, () => {
        stats[p.name] = (stats[p.name] || 0) + 1;
        return `[${p.name}]`;
      });
    }
    return s;
  }
  if (Array.isArray(value)) return value.map(v => mask(v, stats));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, mask(v, stats)]));
  }
  return value;
}

return $input.all().map(item => {
  const stats = {};
  const body = mask(item.json.body, stats);
  return { json: { body, pii_masked: stats } };
});

